import {setDifference} from './set-utils'

// Works for publishers, custom keys, default models, and custom models
type IdentifierType = number | string

export function getNewIdentifiersToAllow<T extends IdentifierType>({
  isAllowlist,
  currentIdentifiersInList,
  selectedIdentifiers,
}: {
  isAllowlist: boolean
  currentIdentifiersInList: Set<T>
  selectedIdentifiers: Set<T>
}) {
  if (isAllowlist) return setDifference(selectedIdentifiers, currentIdentifiersInList)
  return setDifference(currentIdentifiersInList, selectedIdentifiers)
}

export function getNewIdentifiersToBlock<T extends IdentifierType>({
  isAllowlist,
  currentIdentifiersInList,
  selectedIdentifiers,
}: {
  isAllowlist: boolean
  currentIdentifiersInList: Set<T>
  selectedIdentifiers: Set<T>
}) {
  if (isAllowlist) return setDifference(currentIdentifiersInList, selectedIdentifiers)
  return setDifference(selectedIdentifiers, currentIdentifiersInList)
}
