import {useCallback, useEffect, useMemo, useState} from 'react'
import {AlertIcon, PlusIcon} from '@primer/octicons-react'
import {Button, Dialog, Spinner, TreeView} from '@primer/react'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import {buildAllowOrgModelsPayload, buildRestrictOrgModelsPayload} from '../hooks/use-update-organization-access-policy'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import type {DefaultModel, Publisher} from '../types'
import {CustomKeySelectionItem} from './CustomKeySelectionItem'
import {PublisherSelectionItem} from './PublisherSelectionItem'
import {useSelection} from '../contexts/SelectionContext'
import {usePublishers} from '../contexts/PublishersContext'
import {setDifference} from '../utils/set-utils'
import {getAllowedCustomKeyIds, getBlockedCustomKeyIds, getModelIdsByCustomKeyId} from '../utils/custom-keys'

export function AddRuleDialog({
  customKeys,
  models,
  publishers,
}: {
  customKeys: CustomKey[]
  models: Array<CustomModel | DefaultModel>
  publishers: Publisher[]
}) {
  const [isOpen, setIsOpen] = useState(false)
  const {
    allowedCustomModelIds,
    allowedModelKeys,
    didUpdateError,
    isAllowlist,
    isUpdatePending,
    pendingUpdateType,
    updateOrganizationAccessPolicy,
  } = useOrganizationAccessPolicy()
  const {
    fullySelectedCustomKeyIds,
    fullySelectedPublisherIds,
    partiallySelectedCustomKeyIds,
    partiallySelectedPublisherIds,
    selectedCustomModelIds,
    selectedDefaultModelKeys,
  } = useSelection()
  const customKeyIds = customKeys.map(customKey => customKey.id)
  const customModels = useMemo(() => models.filter(model => 'customKeyId' in model), [models])
  const modelIdsByCustomKeyId = useMemo(
    () => getModelIdsByCustomKeyId({customKeys, models: customModels}),
    [customModels, customKeys],
  )
  const allowedCustomKeyIds = getAllowedCustomKeyIds({allowedCustomModelIds, customKeyIds, modelIdsByCustomKeyId})
  const blockedCustomKeyIds = getBlockedCustomKeyIds({allowedCustomModelIds, customKeyIds, modelIdsByCustomKeyId})
  const {allowedPublisherIds, blockedPublisherIds} = usePublishers()
  const defaultModels = useMemo(() => models.filter(model => 'publisherId' in model), [models])
  const blockedCustomModelIds = useMemo(
    () => setDifference(new Set(customModels.map(model => model.id)), allowedCustomModelIds),
    [allowedCustomModelIds, customModels],
  )
  const blockedDefaultModelKeys = useMemo(
    () => setDifference(new Set(defaultModels.map(model => model.key)), allowedModelKeys),
    [allowedModelKeys, defaultModels],
  )

  useEffect(() => {
    if (!isUpdatePending && pendingUpdateType === 'rules') setIsOpen(false)
  }, [isUpdatePending, pendingUpdateType])

  const submitButtonLeadingVisual = useCallback(() => {
    if (pendingUpdateType === 'rules') {
      if (didUpdateError) return <AlertIcon />
      if (isUpdatePending) return <Spinner size="small" />
    }
    return null
  }, [didUpdateError, isUpdatePending, pendingUpdateType])

  const saveSelections = () => {
    if (isUpdatePending) return

    const blockPayload = buildRestrictOrgModelsPayload({
      currentCustomModelIdsInList: isAllowlist ? allowedCustomModelIds : blockedCustomModelIds,
      currentDefaultModelKeysInList: isAllowlist ? allowedModelKeys : blockedDefaultModelKeys,
      currentCustomKeyIdsInList: isAllowlist ? allowedCustomKeyIds : blockedCustomKeyIds,
      currentPublisherIdsInList: isAllowlist ? allowedPublisherIds : blockedPublisherIds,
      isAllowlist,
      selectedCustomModelIds,
      selectedDefaultModelKeys,
      selectedCustomKeyIds: isAllowlist ? partiallySelectedCustomKeyIds : fullySelectedCustomKeyIds,
      selectedPublisherIds: isAllowlist ? partiallySelectedPublisherIds : fullySelectedPublisherIds,
    })
    if (blockPayload !== null) updateOrganizationAccessPolicy(blockPayload)

    const allowPayload = buildAllowOrgModelsPayload({
      currentCustomModelIdsInList: isAllowlist ? allowedCustomModelIds : blockedCustomModelIds,
      currentDefaultModelKeysInList: isAllowlist ? allowedModelKeys : blockedDefaultModelKeys,
      currentCustomKeyIdsInList: isAllowlist ? allowedCustomKeyIds : blockedCustomKeyIds,
      currentPublisherIdsInList: isAllowlist ? allowedPublisherIds : blockedPublisherIds,
      isAllowlist,
      selectedCustomModelIds,
      selectedDefaultModelKeys,
      selectedCustomKeyIds: isAllowlist ? fullySelectedCustomKeyIds : partiallySelectedCustomKeyIds,
      selectedPublisherIds: isAllowlist ? fullySelectedPublisherIds : partiallySelectedPublisherIds,
    })
    if (allowPayload !== null) updateOrganizationAccessPolicy(allowPayload)
  }

  if (publishers.length < 1 && models.length < 1 && customKeys.length < 1) return null

  return (
    <>
      <Button leadingVisual={<PlusIcon size="small" />} onClick={() => setIsOpen(true)} disabled={isUpdatePending}>
        Add models or publishers
      </Button>
      {isOpen && (
        <Dialog
          footerButtons={[
            {
              buttonType: 'primary',
              content: isAllowlist ? 'Update enabled list' : 'Update disabled list',
              disabled: isUpdatePending,
              onClick: saveSelections,
              leadingVisual: submitButtonLeadingVisual,
            },
          ]}
          width="large"
          onClose={() => setIsOpen(false)}
          title={`Select models and publishers to ${isAllowlist ? 'allow' : 'block'}`}
        >
          <p>
            Select models or publishers to <span>{isAllowlist ? 'allow' : 'prevent'}</span> members of your organization{' '}
            <span>{isAllowlist ? 'to use' : 'from using'}</span> them.
          </p>
          <form
            onSubmit={evt => {
              evt.preventDefault()
              saveSelections()
            }}
          >
            <TreeView aria-label="Select models and publishers">
              {customKeys.map(customKey => (
                <CustomKeySelectionItem
                  key={`customKey-${isAllowlist ? 'allow' : 'block'}-${customKey.id}`}
                  customKey={customKey}
                  models={models.filter(m => 'customKeyId' in m)}
                />
              ))}
              {publishers.map(publisher => (
                <PublisherSelectionItem
                  key={`publisher-${isAllowlist ? 'allow' : 'block'}-${publisher.id}`}
                  publisher={publisher}
                  models={defaultModels}
                />
              ))}
            </TreeView>
          </form>
        </Dialog>
      )}
    </>
  )
}

try{ AddRuleDialog.displayName ||= 'AddRuleDialog' } catch {}